    var createTcsPerfilRegraTransacao = function(parent, noCurrent) {
        //Create entity instance
        enableChangeTrack = false;
        var entity = createEntity('TcsPerfilRegraTransacao', { TcsPerfil: parent });
        entity.setDefaults();
        if (typeof entity.OnAdding == 'function') {
            if (!entity.OnAdding()) { dataContext.deleteEntity(entity); return; }
        }
        if (noCurrent !== true) parent.currentTcsPerfilRegraTransacao(entity);
        if (parent && (typeof parent.setCurrentDetails === 'function') && (typeof parent.TcsPerfilRegraTransacaoList === 'function') && parent.TcsPerfilRegraTransacaoList().length == 0) parent.setCurrentDetails('TcsPerfilRegraTransacao');
        if (entity.setParentAsModified) entity.setParentAsModified();
        enableChangeTrack = true;
        return entity;
    };
    
